#SQL JOIN LAB
#Challenge 1: number of films per category:
select category.name, count(film_category.film_id) as num_of_films
from category
left join film_category
on category.category_id=film_category.category_id
group by category.name
order by category.name desc; 
#Retrieve store ID, City and Country for each store
Select st.store_id, city.city, country.country
from store as st
left join address as ad on st.address_id= ad.address_id 
left join city on city.city_id=ad.city_id
left join country on country.country_id=city.country_id; 
#3.Calculate de total revenue generated by each store in dollars
select st.store_id, FORMAT(sum(payment.amount), 'C', 'en-US') as 'total revenue'
from store as st
left join staff on st.store_id=staff.store_id
left join payment on staff.staff_id=payment.staff_id
group by store_id 
order by store_id asc;
#4. Determine the average running time of films for each category.
select ct.name as category, avg(f.length) as avg_running_time
from category as ct
left join film_category as fct on ct.category_id=fct.category_id
left join film as f on fct.film_id=f.film_id
group by ct.name
order by avg_running_time desc; 
# 5. BONUS top 3 running time film categories
select ct.name as category, avg(f.length) as avg_running_time
from category as ct
left join film_category as fct on ct.category_id=fct.category_id
left join film as f on fct.film_id=f.film_id
group by ct.name
order by avg_running_time desc
limit 3; 
#6. top most rented movies descending
select f.title as film_title, count(r.rental_id) as rental_freq
from film as f
left join inventory as i on i.film_id=f.film_id
left join rental as r on r.inventory_id=i.inventory_id
group by title
order by rental_freq desc
limit 10;
# 7. determine if Academy Dinosaur can be rented from store 1
select f.title,
case 
	when st.store_id=1 then 'available'
	else 'not available'
	end as 'availability'
from film as f
left join inventory as i on i.film_id=f.film_id
left join store as st on st.store_id=i.store_id
where f.title = 'Academy Dinosaur';



